126	                metaClient.getStorage().setModificationTime(toPath, modificationTime);
127	              }
128	              metaClient.getStorage().deleteFile(fromPath);
129	            } else {
130	              success = metaClient.getStorage().rename(fromPath, toPath);
131	            }
